const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['app.js','panels.js','effects.js','extended-effects.js','extended-effects-worklet.js','lpf-kernel.js','lpf-validation-harness.js','fx-tempo-capture-worklet.js'];
async function identities(){const r={};for(const f of [...files,'lpf-parameters.js']){const response=await fetch(f,{cache:'no-store'});r[f]=response.ok?await hash(await response.arrayBuffer()):'absent';}return r;}
async function until(fn,label){const end=performance.now()+15000;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
const baseline={Resonance:'1.77',Slope:'12 dB','Min Freq':'400 Hz','Max Freq':'400 Hz'};
function form(){return{open:$('#modal').open,error:$('#fx-parameter-error')?.textContent||'',focus:document.activeElement?.dataset.param||null,fields:[...$('#modal').querySelectorAll('[data-param]')].map(e=>({name:e.dataset.param,value:e.value,invalid:e.getAttribute('aria-invalid'),describedBy:e.getAttribute('aria-describedby'),validity:e.validity.valid}))};}
function edit(values,{save=true}={}){if(!$('#modal').open)$('[data-fx-params="0:0"]').click();for(const[k,v]of Object.entries(values)){const e=$(`[data-param="${k}"]`);e.value=String(v);e.dispatchEvent(new Event('input',{bubbles:true}));}if(save)$('#save-effect').click();return form();}
let app,continueRun;
async function run(){const{engine,state}=app,before=new URL(location.href).searchParams.has('before'),r={startedAt:new Date().toISOString(),scope:'Production browser LPF advanced Save/error/cancel/readback with generated DC+100/2000Hz engine buffer and post-master stereo PCM. Physical graph muted. Not native, hardware, real-file/music or vendor-range/sonic acceptance.',criteria:{settleSeconds:.3,captureSeconds:.3,endpointAmplitudeRelativeTolerance:.01},cases:[],errors:[]},witnesses=[];$('#validation-run').disabled=true;
 const output=()=>{$('#validation-original').textContent=JSON.stringify(r,null,2);$('#validation-results').textContent=JSON.stringify({...r,cases:r.cases.map(c=>({...c,pcm:c.pcm.map(p=>({...p,base64:'Retained in original'}))}))},null,2);};
 async function sample(name,action=()=>{},{reject=false,silence=false}={}){const d=state.decks[0],oldParams=JSON.stringify(state.fx[0][0].params),voice=engine.voices.get(0),c={name,reject,silence};r.cases.push(c);$('#validation-status').textContent='Running '+name;c.form=await action();await sleep(300);c.spec=structuredClone(state.fx[0][0]);c.paramsUnchanged=JSON.stringify(c.spec.params)===oldParams;c.voicePreserved=voice===engine.voices.get(0);c.playing=d.playing;const id=r.cases.length;
  const raw=await Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM timeout')),5000);w.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id,frames:Math.round(engine.ctx.sampleRate*.3)});})));c.pcm=[];for(const p of raw){const b=new Uint8Array(p.data.buffer);c.pcm.push({startFrame:p.startFrame,frames:p.data.length,sha256:await hash(b),base64:base64(b)});}c.passed=(!reject||c.paramsUnchanged&&c.form?.open&&!!c.form.error)&&(silence||c.playing&&c.voicePreserved);output();}
 try{r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical graph must be muted');await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;const d=state.decks[0],b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*180,engine.ctx.sampleRate);for(let ch=0;ch<2;ch++)for(let i=0;i<b.length;i++)b.getChannelData(ch)[i]=.15+.02*Math.sin(2*Math.PI*100*i/b.sampleRate)+.02*Math.sin(2*Math.PI*2000*i/b.sampleRate);Object.assign(d.track,{bpm:120,duration:180,analyzed:true});Object.assign(d,{rate:1,position:0,keylock:false,keyShift:0,sync:false,syncState:'off',loop:false,reverse:false});engine.buffers.set(d.track.id,b);engine.clearDeckScratchCache(0);engine.mix(0,'level',.8);r.sampleRate=engine.ctx.sampleRate;
  await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);for(let ch=0;ch<2;ch++){const w=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,ch);w.connect(engine.ctx.destination);witnesses.push(w);}
  $('[data-panel="fx"]').click();const depth=$('[data-fx-depth="0:0"]');depth.value='100';depth.dispatchEvent(new Event('input',{bubbles:true}));edit(baseline);$('[data-fx-on="0:0"]').click();$('[data-action="play"][data-deck="0"]').click();await until(()=>d.playing&&!d.processing,'Playback');await sample('Valid12dB/400Hz baseline');
  await sample('Mixed valid changes with NaN minimum are rejected atomically',()=>edit({...baseline,Slope:'18 dB','Min Freq':'NaN','Max Freq':'4 kHz'}),{reject:true});$('#validation-continue').disabled=false;$('#validation-status').textContent='Invalid-save checkpoint ready; output muted. View the dialog, close it if open, then Continue.';await new Promise(resolve=>continueRun=resolve);$('#validation-continue').disabled=true;
  if(!before){
   await sample('Crossed minimum/maximum are rejected atomically',()=>edit({...baseline,Resonance:'2','Min Freq':'900 Hz','Max Freq':'800 Hz'}),{reject:true});
   await sample('Unsupported slope and resonance are both rejected',()=>edit({...baseline,Resonance:'-1',Slope:'19 dB'}),{reject:true});
   await sample('Corrected exponent and kHz values save canonical live settings',()=>edit({Resonance:'2e0',Slope:'18 dB/octave','Min Freq':'.4 kHz','Max Freq':'400 Hz'}));
   await sample('Cancel valid draft edits preserves the last saved setting',()=>{edit({Resonance:'5','Min Freq':'800 Hz','Max Freq':'1 kHz'},{save:false});$('#modal-close').click();$('[data-fx-params="0:0"]').click();r.cancelReadback=form();$('#modal-close').click();return form();});
  }
  if($('#modal').open)$('#modal-close').click();$('[data-action="play"][data-deck="0"]').click();await until(()=>!d.playing,'Stop');await sample('Normal Stop produces silence',()=>{},{silence:true});
 }catch(e){r.errors.push({message:e.message,stack:e.stack});}finally{for(const d of state.decks)engine.pause(d);for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.completed=r.sourceStable&&!r.errors.length&&r.cases.length===(before?3:7)&&r.cases.every(c=>c.passed);r.finishedAt=new Date().toISOString();output();const a=$('#validation-download');a.href=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));a.download='lpf-validation-original.json';a.hidden=false;$('#validation-status').textContent=r.completed?'Scoped LPF validation workflow passed; stopped':'LPF validation failures retained; stopped';}}
$('#validation-run').onclick=()=>run();$('#validation-continue').onclick=()=>continueRun?.();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#validation-run').disabled=false;$('#validation-status').textContent='Ready';}boot().catch(e=>$('#validation-status').textContent=e.message);
